        {"param": "data_width", "low": 10, "high": 22, "choices": null},
        {"param": "n_iter", "low": 9, "high": 22, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "family": "iterative",
      "budget_share": 0.60
    },
    {
      "why": "Shares the datapath but chains k rotations per cycle, so it sits between iterative and pipelined in area. Cycles are not an objective here, so it is probably dominated, but small k (2-3) keeps it close to iterative and it is a cheap hedge in case the cost model favours it at some accuracy points.",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 22, "choices": null},
